import sys

def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0
    sys.setrecursionlimit(200000)

    class CalcError(Exception):
        pass

    def skip():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def tdiv(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def parse_expr():
        nonlocal i
        skip()
        v = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                rhs = parse_term()
                v = v + rhs if op == '+' else v - rhs
            else:
                return v

    def parse_term():
        nonlocal i
        skip()
        v = parse_unary()
        while True:
            skip()
            if i < n and s[i] in '*/%':
                op = s[i]
                i += 1
                rhs = parse_unary()
                if op == '*':
                    v *= rhs
                else:
                    if rhs == 0:
                        raise CalcError
                    if op == '/':
                        v = tdiv(v, rhs)
                    else:
                        v = v - rhs * tdiv(v, rhs)
            else:
                return v

    def parse_unary():
        nonlocal i
        skip()
        if i < n and s[i] == '-':
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal i
        skip()
        base = parse_primary()
        skip()
        if i < n and s[i] == '^':
            i += 1
            exp = parse_unary()
            if exp < 0:
                raise CalcError
            return pow(base, exp)
        return base

    def parse_primary():
        nonlocal i
        skip()
        if s[i] == '(':
            i += 1
            v = parse_expr()
            skip()
            i += 1  # consume ')'
            return v
        j = i
        while j < n and s[j].isdigit():
            j += 1
        v = int(s[i:j])
        i = j
        return v

    try:
        skip()
        return parse_expr()
    except CalcError:
        return "error"
